(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-466":{scenario:{company:"Vĩnh An Consulting",supervisor:{name:"Trịnh Văn Thắng",role:{vi:"Trưởng phòng Hành chính - Quản trị",en:"Head of Administration & Facilities"}},ref_code:"FAC-0904",title:{vi:"Đúng bình chữa cháy. Đủ chỗ ngồi. Mua sắm minh bạch.",en:"Right extinguisher. Enough seats. Transparent purchasing."},brief:{vi:"Bạn lập kế hoạch bố trí văn phòng mới FAC-0904 cho 136 nhân viên làm việc kết hợp. Dữ liệu quẹt thẻ 3 tháng: trung bình 65% nhân viên có mặt mỗi ngày, ngày cao điểm thứ Ba có mặt 75%. Phòng máy chủ mới cần bình chữa cháy xách tay phù hợp đám cháy thiết bị điện đang mang điện. Đối chiếu kế hoạch nháp với hồ sơ đã duyệt, sửa loại bình chữa cháy và số chỗ ngồi cần bố trí, rồi lập báo cáo có căn cứ.",en:"You are planning new office layout FAC-0904 for 136 hybrid employees. Three months of badge data show 65% average daily attendance and 75% on the Tuesday peak. The new server room needs portable extinguishers suitable for fires in live electrical equipment. Compare the draft plan with the approved file, correct the extinguisher type and the number of workstations required, then write an evidence-based report."},reference_title:{vi:"Phương án PCCC & báo cáo sử dụng văn phòng đã duyệt · FAC-0904",en:"Approved fire plan & office utilisation report · FAC-0904"},fields:[{id:"EXT_TYPE",label:{vi:"Loại bình chữa cháy cho phòng máy chủ",en:"Extinguisher type for the server room"},initial:"FOAM",expected:"CO2",choices:["WATER","FOAM","CO2"],reference:"Phương án PCCC cơ sở đã duyệt",hint:{vi:"Nước và bọt dẫn điện, làm hỏng thiết bị; đám cháy thiết bị điện dùng khí CO2, không để lại cặn.",en:"Water and foam conduct electricity and damage equipment; electrical fires call for CO2, which leaves no residue."}},{id:"SEATS",label:{vi:"Số chỗ ngồi cần bố trí",en:"Workstations required"},initial:"89",expected:"102",reference:"Báo cáo sử dụng văn phòng 3 tháng",ref_value:{vi:"136 nhân viên; có mặt trung bình 65%; có mặt ngày cao điểm 75%",en:"136 employees; average attendance 65%; peak-day attendance 75%"},hint:{vi:"Bản nháp tính theo mức có mặt trung bình; chỗ ngồi phải đủ cho ngày đông nhất.",en:"The draft used average attendance; seating must cover the busiest day."}}],sop32:{vi:"Số chỗ ngồi = tổng nhân viên x tỷ lệ có mặt ngày cao điểm, làm tròn lên số nguyên; không dùng tỷ lệ trung bình để tránh thiếu chỗ vào ngày đông nhất.",en:"Workstations = total employees x peak-day attendance rate, rounded up to a whole number; never use the average rate, or the busiest day runs short."},context:{label:"KẾ HOẠCH BỐ TRÍ / FAC-0904",metrics:[{label:{vi:"Tổng nhân viên",en:"Total employees"},value:"136"},{label:{vi:"Có mặt trung bình",en:"Average attendance"},value:"65%"},{label:{vi:"Có mặt ngày cao điểm",en:"Peak-day attendance"},value:"75%"}]},crisis:{vi:"Nhà thầu nội thất nhắn riêng: “Chọn báo giá bên em nhé, cao hơn hai bên kia 8% nhưng em gửi lại 5% tiền mặt. Trưởng phòng đang nghỉ phép, mình chốt luôn hôm nay cho kịp tiến độ.”",en:"The furniture contractor messages you privately: “Go with our quote, it is 8% above the other two but I will give you 5% back in cash. Your manager is on leave, let's close it today to stay on schedule.”"},options:{safe:{vi:"Từ chối nhận tiền gửi lại; báo Trưởng phòng Hành chính và bộ phận kiểm soát nội bộ bằng văn bản, so sánh ba báo giá theo tiêu chí đã duyệt và chờ người có thẩm quyền phê duyệt.",en:"Refuse the kickback; report it in writing to the Head of Administration and Internal Control, compare the three quotes on approved criteria and wait for the authorised approver."},shortcut:{vi:"Chốt báo giá của nhà thầu này ngay hôm nay và nhận khoản gửi lại 5%.",en:"Sign this contractor's quote today and take the 5% back."},wait:{vi:"Không trả lời nhà thầu và để hồ sơ mua sắm treo đến khi trưởng phòng về.",en:"Ignore the contractor and leave the purchase on hold until the manager returns."}},questions:{vi:["Vì sao phòng máy chủ dùng bình CO2 và văn phòng cần 102 chỗ ngồi? Nêu dữ liệu và rủi ro nếu giữ bản nháp.","Nhận tiền gửi lại từ nhà thầu gây hậu quả gì cho công ty và cá nhân? Bạn bảo đảm quy trình mua sắm minh bạch thế nào?"],en:["Why does the server room need CO2 extinguishers, and why does the office need 102 workstations? State the data and the risk of keeping the draft.","What are the consequences of a contractor kickback for the company and for you? How do you keep purchasing transparent?"]},hints:{vi:["So kế hoạch nháp với phương án PCCC: đám cháy loại nào có thể xảy ra trong phòng máy chủ?","Nhân tổng nhân viên với tỷ lệ có mặt ngày cao điểm rồi làm tròn lên theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi lợi ích cá nhân từ nhà cung cấp phải được từ chối và báo cáo."],en:["Compare the draft with the fire plan: what kind of fire can break out in a server room?","Multiply total employees by the peak-day attendance rate and round up as in SOP 3.2.","Re-read SOP 4.2: any personal benefit from a supplier must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên hành chính văn phòng và quản trị cơ sở bảo đảm văn phòng vận hành an toàn, tiện nghi, tiết kiệm: quản lý tài sản, mua sắm, văn thư lưu trữ, sự kiện nội bộ, nhà cung cấp dịch vụ, an ninh, phòng cháy chữa cháy và bố trí không gian làm việc. Nghề đòi hỏi tổ chức tốt, tính toán chi phí, hiểu quy định an toàn và giữ liêm chính trong mua sắm.",en:"An office administration and facilities officer keeps the workplace safe, comfortable and cost-effective: assets, purchasing, records and archives, internal events, service vendors, security, fire safety and space planning. The role requires strong organisation, cost calculation, knowledge of safety rules and integrity in purchasing."},responsibilities:{vi:["Quản lý tài sản, trang thiết bị, văn phòng phẩm và kiểm kê định kỳ.","Tổ chức mua sắm theo quy trình báo giá, phê duyệt và quản lý hợp đồng dịch vụ.","Quản lý văn thư, con dấu, lưu trữ hồ sơ và lịch phòng họp.","Duy trì an ninh, vệ sinh, phòng cháy chữa cháy, tổ chức diễn tập và kiểm tra thiết bị.","Lập kế hoạch bố trí không gian, chuyển văn phòng và tối ưu chi phí vận hành."],en:["Manage assets, equipment and supplies and run periodic stock counts.","Run purchasing through quotes and approvals and manage service contracts.","Manage correspondence, company seals, records archives and meeting room schedules.","Maintain security, cleaning and fire safety, run drills and inspect equipment.","Plan space, office moves and operating cost optimisation."]},competencies:[{name:{vi:"Tổ chức & điều phối",en:"Organisation & coordination"},desc:{vi:"Lên kế hoạch, theo dõi đầu việc và phối hợp nhiều nhà cung cấp cùng lúc.",en:"Plan, track tasks and coordinate several vendors at once."}},{name:{vi:"Quản lý nhà cung cấp",en:"Vendor management"},desc:{vi:"So sánh báo giá, đánh giá chất lượng dịch vụ và quản lý hợp đồng, cam kết SLA.",en:"Compare quotes, assess service quality and manage contracts and SLAs."}},{name:{vi:"An toàn cơ sở",en:"Facility safety"},desc:{vi:"Nắm phương án PCCC, thiết bị chữa cháy, lối thoát nạn và quy trình ứng phó sự cố.",en:"Know the fire plan, extinguishing equipment, escape routes and incident response."}},{name:{vi:"Tính toán chi phí, không gian",en:"Cost & space planning"},desc:{vi:"Dự toán ngân sách, tính nhu cầu chỗ ngồi, diện tích và điện năng.",en:"Build budgets and calculate seating, floor area and power needs."}},{name:{vi:"Liêm chính",en:"Integrity"},desc:{vi:"Từ chối hoa hồng, quà tặng có điều kiện và công khai xung đột lợi ích.",en:"Refuse kickbacks and conditional gifts and disclose conflicts of interest."}}],knowledge:{vi:["Pháp luật về phòng cháy, chữa cháy và cứu nạn, cứu hộ: trách nhiệm người đứng đầu cơ sở, phương án chữa cháy, huấn luyện, diễn tập.","Phân loại đám cháy và chất chữa cháy: nước cho chất rắn thông thường, bọt cho chất lỏng cháy, CO2 hoặc bột cho thiết bị điện.","Nghị định 30/2020/NĐ-CP về công tác văn thư, bắt buộc với cơ quan nhà nước, doanh nghiệp khác dùng làm chuẩn tham khảo.","ISO 41001: hệ thống quản lý cơ sở vật chất (facility management).","Nguyên tắc mua sắm minh bạch: tối thiểu ba báo giá, phân quyền phê duyệt, khai báo xung đột lợi ích."],en:["Fire prevention, fighting and rescue law: duties of the facility head, firefighting plans, training and drills.","Fire classes and agents: water for ordinary solids, foam for flammable liquids, CO2 or powder for electrical equipment.","Decree 30/2020/ND-CP on records management, mandatory for state bodies and a reference standard for other companies.","ISO 41001: facility management systems.","Transparent purchasing principles: at least three quotes, delegated approval limits and conflict of interest disclosure."]},tools:["Phần mềm quản lý tài sản","Hệ thống đặt phòng họp và chỗ ngồi","Hệ thống kiểm soát ra vào","Phần mềm quản lý yêu cầu sửa chữa","Bảng tính dự toán ngân sách","Phần mềm quản lý văn bản, lưu trữ"],kpis:{vi:["Tỷ lệ yêu cầu sửa chữa, hỗ trợ được xử lý đúng SLA.","Chi phí vận hành văn phòng trên mỗi nhân viên so với ngân sách.","Tỷ lệ thiết bị PCCC được kiểm tra đúng hạn và kết quả diễn tập.","Tỷ lệ hồ sơ mua sắm đủ ba báo giá và phê duyệt đúng thẩm quyền."],en:["Share of repair and support requests closed within SLA.","Office operating cost per employee against budget.","Share of fire equipment inspected on time and drill results.","Share of purchases with three quotes and approval at the right level."]},day:[{time:"08:00",vi:"Đi kiểm tra văn phòng, lối thoát nạn, thiết bị PCCC và vệ sinh đầu ngày.",en:"Walk the office to check escape routes, fire equipment and cleaning."},{time:"09:30",vi:"Xử lý yêu cầu sửa chữa, cấp phát văn phòng phẩm và tài sản.",en:"Handle repair requests and issue supplies and assets."},{time:"11:00",vi:"So sánh báo giá nội thất và lập tờ trình phê duyệt.",en:"Compare furniture quotes and prepare the approval memo."},{time:"14:00",vi:"Họp nhà thầu thi công văn phòng mới, kiểm tra tiến độ và an toàn công trường.",en:"Meet the fit-out contractor to check progress and site safety."},{time:"16:30",vi:"Cập nhật sổ tài sản, lịch phòng họp và báo cáo chi phí tuần.",en:"Update the asset register, room schedule and weekly cost report."}],mistakes:{vi:["Trang bị sai loại bình chữa cháy, như dùng bình bọt hoặc nước cho phòng thiết bị điện.","Tính nhu cầu chỗ ngồi theo mức có mặt trung bình, gây thiếu chỗ vào ngày cao điểm.","Chia nhỏ đơn hàng để né phê duyệt hoặc nhận hoa hồng từ nhà cung cấp."],en:["Fitting the wrong extinguisher, such as foam or water in an electrical equipment room.","Sizing seating on average attendance, leaving people without desks on peak days.","Splitting orders to dodge approval limits or taking supplier kickbacks."]},career:[{vi:"Nhân viên hành chính",en:"Administrative assistant"},{vi:"Chuyên viên hành chính - quản trị",en:"Office administration officer"},{vi:"Trưởng nhóm quản trị cơ sở",en:"Facilities team lead"},{vi:"Trưởng phòng hành chính - quản trị",en:"Head of administration & facilities"}],glossary:[{term:"Facility management",vi:"Quản trị cơ sở vật chất và dịch vụ hỗ trợ để nơi làm việc vận hành hiệu quả.",en:"Managing buildings and support services so the workplace runs effectively."},{term:"Desk sharing ratio",vi:"Tỷ lệ số chỗ ngồi trên số nhân viên trong mô hình làm việc kết hợp.",en:"The ratio of workstations to employees in a hybrid workplace."},{term:"SLA",vi:"Thỏa thuận mức dịch vụ quy định thời gian và chất lượng phản hồi của nhà cung cấp.",en:"Service level agreement setting a vendor's response time and quality."},{term:"CO2 extinguisher",vi:"Bình chữa cháy khí CO2 dùng cho thiết bị điện, không để lại cặn; cần thông gió sau khi xả trong phòng kín.",en:"A carbon dioxide extinguisher for electrical equipment that leaves no residue; ventilate after use in closed rooms."},{term:"Conflict of interest",vi:"Tình huống lợi ích cá nhân có thể ảnh hưởng tới quyết định công việc.",en:"A situation where personal interest could sway a work decision."}],quiz:[{q:{vi:"Văn phòng có 200 nhân viên, ngày cao điểm có mặt 70%. Cần bố trí bao nhiêu chỗ ngồi?",en:"An office has 200 employees and 70% attend on the peak day. How many workstations are needed?"},options:{vi:["130","200","140","150"],en:["130","200","140","150"]},answer:2,explain:{vi:"200 x 70% = 140 chỗ; tính theo ngày cao điểm để không thiếu chỗ.",en:"200 x 70% = 140 seats; size for the peak day so no one is left without a desk."}},{q:{vi:"Tủ điện đang mang điện bị cháy. Nên dùng phương tiện nào?",en:"A live electrical cabinet catches fire. What should you use?"},options:{vi:["Nước","Bình CO2","Bình bọt","Cát ướt"],en:["Water","A CO2 extinguisher","A foam extinguisher","Wet sand"]},answer:1,explain:{vi:"CO2 không dẫn điện và không để lại cặn; nước, bọt có thể gây điện giật.",en:"CO2 does not conduct electricity and leaves no residue; water and foam risk electric shock."}},{q:{vi:"Nhà cung cấp đề nghị gửi lại 5% nếu được chọn. Bạn làm gì?",en:"A supplier offers 5% back if chosen. What do you do?"},options:{vi:["Nhận vì không ai biết","Nhận rồi nộp vào quỹ phòng","Lặng lẽ chọn nhà cung cấp khác","Từ chối, báo cáo bằng văn bản và giữ quy trình ba báo giá"],en:["Accept, nobody will know","Accept and put it in the team fund","Quietly pick another supplier","Refuse, report it in writing and keep the three-quote process"]},answer:3,explain:{vi:"Khoản gửi lại là hối lộ thương mại; phải từ chối, báo cáo và lựa chọn theo tiêu chí minh bạch.",en:"A kickback is commercial bribery; refuse it, report it and select on transparent criteria."}},{q:{vi:"ISO 41001 là tiêu chuẩn về lĩnh vực nào?",en:"What does ISO 41001 cover?"},options:{vi:["Hệ thống quản lý cơ sở vật chất","An toàn thông tin","Quản lý chất lượng","Quản lý môi trường"],en:["Facility management systems","Information security","Quality management","Environmental management"]},answer:0,explain:{vi:"ISO 41001 quy định yêu cầu cho hệ thống quản lý cơ sở vật chất; ISO 27001, 9001, 14001 là các lĩnh vực khác.",en:"ISO 41001 sets requirements for facility management systems; ISO 27001, 9001 and 14001 cover other fields."}}],tools_en:["Asset management software","Meeting room and desk booking system","Access control system","Maintenance request management software","Budget estimate spreadsheet","Document and records management software"]}}})})(window.KKR);
